deps = {"app": ["feed", "chat"], "feed": ["ui"], "chat": ["ui"], "ui": ["core"]}
def rebuild(changed, exported):
    out, frontier = {changed}, [changed]
    while frontier:
        m = frontier.pop()
        for user, ds in deps.items():
            if m in ds and user not in out:
                out.add(user)
                if exported.get(user, False):   # api 로 노출하면 그 위도 다시
                    frontier.append(user)
    return sorted(out)
print("api:", rebuild("core", {"ui": True, "feed": True, "chat": True}))
print("implementation:", rebuild("core", {}))

def gate(stage, hours, users, crash_free, anr_rate, min_h=24, min_users=20000):
    if crash_free < 0.995 or anr_rate > 0.0047:
        return "멈춤"
    if hours < min_h or users < min_users:
        return "기다림"
    return "다음 단계"
for row in [(5, 30, 41000, 0.9991, 0.0021), (5, 30, 41000, 0.9931, 0.0021),
            (30, 10, 260000, 0.9990, 0.0020), (30, 26, 260000, 0.9990, 0.0052)]:
    print(row[0], "% ->", gate(*row))
